/* ###### 8.1 Dashboard One  ###### */

.az-content-dashboard {
  padding-top: 20px;
  @include media-breakpoint-up(lg) { padding-top: 30px; }
}

.az-dashboard-one-title {
  margin-bottom: 20px;

  @include media-breakpoint-up(sm) {
    display: flex;
    align-items: center;
    justify-content: space-between;
  }

  @include media-breakpoint-up(lg) { margin-bottom: 30px; }
}

.az-dashboard-title {
  font-size: 22px;
  font-weight: 700;
  color: $gray-900;
  letter-spacing: -1px;
  margin-bottom: 3px;
}

.az-dashboard-text {
  font-size: 13px;
  margin-bottom: 0;
}

.az-dashboard-date {
  display: flex;
  align-items: center;
  margin-top: 20px;

  @include media-breakpoint-up(sm) { margin-top: 0; }

  .date {
    display: flex;

    > div:first-child {
      font-size: 32px;
      font-family: Arial, sans-serif;
      font-weight: 500;
      color: $gray-900;
      line-height: .9;

      @include media-breakpoint-up(md) { font-size: 36px; }
    }

    > div:last-child {
      margin-left: 5px;

      span {
        display: block;
        color: $gray-900;
        font-weight: 700;
        font-size: 12px;
        line-height: 1.2;
        letter-spacing: -.5px;

        @include media-breakpoint-up(md) { font-size: 13px; }

        &:last-child {
          color: $gray-600;
          font-weight: 400;
        }
      }
    }
  }

  > i {
    font-size: 21px;
    line-height: 0;
    display: block;
    margin: 0 15px;
    color: $gray-500;

    @include media-breakpoint-up(md) {
      margin: 0 20px;
      font-size: 24px;
    }
  }
}

.az-dashboard-nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid $gray-300;
  margin-bottom: 20px;

  .nav-link {
    font-size: 12px;
    padding: 5px 10px 8px;
    display: flex;
    align-items: center;
    line-height: 1;

    @include media-breakpoint-up(sm) { font-size: $font-size-base; }
    @include media-breakpoint-up(lg) { padding: 5px 15px 10px; }

    @include hover-focus() { color: $az-color-primary; }

    + .nav-link { border-left: 1px solid $gray-300; }
  }

  .nav:first-child {
    .nav-link {
      color: $gray-900;
      display: none;

      @include media-breakpoint-up(sm) { display: block; }

      @include hover-focus() { color: $az-color-primary; }

      &.active { color: $az-color-primary; }

      &:first-child { padding-left: 0; }

      &:first-child,
      &:last-child {
        display: block;
      }
    }
  }

  .nav:last-child {
    .nav-link {
      color: $gray-700;
      display: none;

      @include media-breakpoint-up(md) { display: block; }

      @include hover-focus() { color: $az-color-primary; }

      i {
        font-size: 16px;
        margin-right: 7px;
        line-height: 0;
      }

      &:last-child {
        padding-right: 0;
        display: block;

        i { margin-right: 0; }

        @include media-breakpoint-up(md) { display: none; }
      }
    }
  }
}

.card-dashboard-one {
  position: relative;
  border-color: $gray-300;

  .card-header {
    padding: 20px;
    background-color: transparent;

    @include media-breakpoint-up(sm) {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
    }

    .card-title {
      color: $gray-900;
      font-weight: 700;
      font-size: 14px;
      line-height: 1;
      margin-bottom: 3px;
    }

    .card-text {
      margin-bottom: 0;
    }

    .btn-group {
      margin-top: 15px;
      @include media-breakpoint-up(sm) { margin-top: 0; }

      .btn {
        font-size: 12px;
        font-weight: 500;
        padding: 5px 10px;
        min-height: inherit;
        background-color: #fff;
        color: $gray-600;
        border: 1px solid $gray-300;

        @include hover-focus() {
          background-color: $gray-100;
          border-color: $gray-300;
        }

        + .btn { margin-left: -1px; }

        &.active {
          color: $gray-900;
          background-color: $gray-200;
          border-color: $gray-300;
        }
      }
    }
  }

  .card-body {
    padding: 10px 0 20px;
    position: relative;
    overflow: hidden;

    .flot-chart-wrapper {
      position: relative;
      margin-left: -28px;
      margin-right: -20px;
    }

    .flot-chart {
      width: 100%;
      height: 150px;

      @include media-breakpoint-up(sm) { height: 275px; }
      @include media-breakpoint-only(lg) { height: 252px; }

      .flot-y-axis > div {
        transform: translateX(50px);
        text-shadow: 1px 1px rgba(#fff, .75);
        color: $body-color;
        font-weight: 700;
        font-size: 11px;
      }

      .flot-x-axis > div {
        color: $gray-500;
        font-weight: 500;
        font-size: 11px;
      }
    }
  }

  .card-body-top {
    display: flex;
    align-items: flex-start;
    flex-wrap: wrap;
    padding-left: 20px;

    @include media-breakpoint-up(sm) {
      position: absolute;
      top: -5px;
      left: 20px;
      z-index: 5;
      padding-left: 0;
    }

    > div {
      flex-basis: 50%;
      @include media-breakpoint-up(sm) { flex-basis: auto; }

      + div {
        @include media-breakpoint-up(sm) { margin-left: 30px; }
      }
    }

    label {
      font-size: 12px;
      margin-bottom: 3px;

      @include media-breakpoint-up(sm) { font-size: $font-size-base; }
    }

    h2 {
      font-size: 20px; //$font-size-base;
      font-weight: 600;
      font-family: 'Archivo', $font-family-base;
      color: $gray-900;

      @include media-breakpoint-up(sm) {
        font-size: 24px;



      color: $gray-900;
      display: flex;
      align-items: baseline;
      margin-bottom: 2px;
      line-height: 1;
      letter-spacing: -1px;




      font-family: 'Archivo', $font-family-base;
      display: flex;
      align-items: baseline;
      margin-bottom: 15px;      small {        font-size: 12px;
        font-weight: 400;

        margin-left: 5px;


    > small {
      font-size: 11px;
      display: none;
      color: $gray-600;
  .card-body {
    padding: 0 0 0 20px;
    display: flex;  .card-header {
    background-color: transparent;



  .card-text {
    font-size: 13px;
    margin-bottom: 0;
  }

  .card-body { padding: 0; }
}

.card-dashboard-four {
  border-radius: 0;
  border-color: $gray-300;
  padding: 20px;
  height: 100%;

  .card-header {
    padding: 0 0 20px;
    background-color: transparent;
  }

    font-size: 14px;
    color: $gray-900;
    margin-bottom: 0;
  }

  .card-body {
    padding: 0;
    @include media-breakpoint-up(lg) { padding: 0 20px; }
  }

  .chart {
    width: calc(100vw - 80px);
    height: 200px;

    @media (min-width: 375px) { width: auto; }

    @include media-breakpoint-up(lg) { height: 85%; }
  }
}

.card-dashboard-five {
  border-color: $gray-300;
  padding: 20px;

  .card-header {
    padding: 0;
    background-color: transparent;
  }

  .card-title {
    font-weight: 700;
    font-size: 14px;
    color: $gray-900;
    margin-bottom: 5px;
  }

  .card-text {
    display: block;
    font-size: 12px;
  }

  .card-body {
    padding: 20px 0 5px;

    label {
      display: block;
      margin-bottom: 2px;
      font-size: 12px;
    }

    h4 {
      color: $gray-900;
      font-family: 'Archivo', $font-family-base;
      font-weight: 700;
      letter-spacing: -.5px;
      margin-bottom: 0;
    }
  }

  .card-chart {
    width: 40px;
    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 10px;

    @include media-breakpoint-up(sm) {
      margin-bottom: 0;
      margin-right: 10px;
    }
  }
}

.card-table-one {
  padding: 20px 20px 10px;
  border-color: $gray-300;

  .card-title {
    font-size: 14px;
    font-weight: 700;
    margin-bottom: 5px;
  }

  .table-responsive {
    width: calc(100vw - 80px);
    @include media-breakpoint-up(sm) { width: 100%; }
  }

  .table {
    margin-bottom: 0;

    thead,
    tbody {
      tr > th,
      tr > td {
        vertical-align: middle;
        white-space: nowrap;
        padding-right: 2px;

        @include media-breakpoint-up(md) {
          padding-left: 0;
          padding-right: 0;
        }

        &:nth-child(3),
        &:nth-child(4),
        &:nth-child(5) { text-align: right; }

        strong { color: $gray-900; }
      }
    }
  }

  .flag-icon {
    font-size: 20px;
    line-height: 1;
    @include border-radius(100%);
  }
}
/* ###### 6.1 Content  ###### */

.az-content-left-show {
  @media (max-width: 575px) { overflow: hidden; }

  .az-content-left {
    @include media-breakpoint-down(md) {
      display: block;
      position: fixed;
      top: 0;
      bottom: 0;
      left: 0;
      background-color: #fff;
      z-index: 800;
      border-right: 1px solid $gray-300;
      box-shadow: 0 0 3px rgba($gray-900, .1);
      overflow-y: auto;
    }
  }

  .az-content-body {
    @media (max-width: 575px) { display: none; }
  }
}

.az-content-body-show {
  @include media-breakpoint-down(md) {
    .az-header {
      .az-header-menu-icon { display: none; }
      .az-header-left .az-header-arrow { display: block; }  }
}

.az-content {
  @include media-breakpoint-up(lg) { padding: 30px 0; }

  .container,
  .container-fluid {
    display: flex;
    padding-left: 20px;

  .container {
    @include media-breakpoint-up(lg) { padding: 0; }
    @include media-breakpoint-down(md) { max-width: none; }
  }
}

.az-content-app {
  padding-top: 20px;

  @include media-breakpoint-up(lg) {
  }

  .container,
  .container-fluid {
    height: 100%;
    padding: 0;
  }
}

.az-content-left {
  width: 100%;
  position: relative;
  padding: 0 20px 20px;
  flex-shrink: 0;
  display: none;

  @include media-breakpoint-up(sm) { width: 280px; }
  @include media-breakpoint-up(lg) {
    display: block;
    padding: 0;
  }
}

.az-content-header {
  height: $az-height-header-mobile;
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;

  @include media-breakpoint-up(lg) { display: none; }

